using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class AvynALlyin : LayoutBase
{
    public AvynALlyin()
    {
        Name = LayoutNamesEnums.AvynALlyin;
        Owner = "Andrew Bailey";
        LayoutByLayoutVideos = ["https://youtu.be/GDorExnriDE"];
        Description = "After six years of success with the layout Llandovnodd, it was decided to model the next fictitious village up the coast, called Avyn-a-Llyin. After nearly 20 years on the exhibition circuit the current owner took the layout over from his brother, David Bailey. The pier is of timber construction with each upright individually screwed into place, and most of the buildings are scratch built in Linka and plasticard - two of the roofs are genuine hand cut Welsh slate and three are thatched with plumbers hemp in Pendon style. The sea is literally dozens of coats of non-drip varnish over a mixture of sand and ballast, while the beach is real sand up to 20mm deep. There are over 200 figures on the layout and, in case you cannot find them, the nudists are at the back of the beach under the sea wall. The track is Peco with Seep and Cobalt electrics, ballasted with a mix of granite, limestone and sand, and most of the stock is kit built with a few scratch built, 3D printed and ready-to-run items. Avyn-a-Llyin was first exhibited in October 1989 and has since won numerous trophies, as well as appearing in Railway Modeller and Hornby Magazine. Since 2012 the layout has been undergoing refurbishment to keep it looking fresh.";
    }
}